function GetPlayerDanceActionWithConfigID(danceActionConfigID, actionIndex, idSequence)
	local danceActionConfig = PlayerDanceActionConfig[danceActionConfigID];
	if danceActionConfig == nil then
		return nil
	end
	return danceActionConfig[actionIndex][idSequence]
end

