	BOY_HUG = 103,		--  成女抱男孩
	GIRL_ONBACK = 104,	--	成男扛女孩
	BOY_ONBACK = 105,	--	成男扛男孩
}

BindLoverDanceToDance = {}
BindLoverDanceToDance.Configs = 
{
	maxHeightDiff = 4,
	mainObjLeftOffset = 1, 
	mainObjBackOffset = 1,
}

function BindLoverDanceToDance:GetDoubleDanceConfig()	
	local ret_table = {}
		ret_table[1] = self.Configs.maxHeightDiff
		ret_table[2] = self.Configs.mainObjLeftOffset
		ret_table[3] = self.Configs.mainObjBackOffset
	return unpack(ret_table)
end

